verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs = require("fs")
const { pathToFileURL } = require("url")
const { join } = require("path")
const fail = (m) => { console.error(m); process.exit(1) }
const at = (f) => pathToFileURL(join(process.cwd(), f)).href
const DRAWER = "components/calendar-suite/suite-details.tsx"
const TEST = "components/calendar-suite/suite-details.render.test.tsx"
import(at("lib/calendar/series-choice.ts")).then((sc) => {
  const rep = { kind: "pencil", repeat: "FREQ=WEEKLY", occurrenceDate: "2026-10-14" }
  const plan = sc.planEntryDelete(rep)
  if (plan.ask !== true) fail("a repeating calendar entry no longer forces the delete question, so one press on an occurrence hard-deletes the whole series again (LIVE-533, the owner data loss)")
  if (plan.immediate !== "nothing") fail("a repeating entry offers an IMMEDIATE delete of " + plan.immediate + ": there is a path from one press to a destroyed series again")
  if (plan.thisDate !== "2026-10-14") fail("the occurrence day is no longer carried into the plan, so the only honest choice (skip this date) cannot be offered")
  if (sc.resolveSeriesDeleteChoice("thisDate", plan) !== "skipThisDate") fail("the this-date-only choice no longer resolves to the exception-date write, which is the whole repair: it writes exception_dates and leaves the row alone")
  if (sc.resolveSeriesDeleteChoice("series", plan) !== "deleteRow") fail("the whole-series choice no longer reaches the row delete, so the deliberate destructive path is broken")
  if (sc.resolveSeriesDeleteChoice("keep", plan) !== "nothing") fail("the way out of the delete dialog writes something")
  const bare = sc.planEntryDelete({ kind: "pencil", repeat: "FREQ=WEEKLY", occurrenceDate: null })
  if (bare.ask !== true) fail("a repeating entry opened away from one occurrence skips the question, so it can be hard-deleted in one press")
  if (sc.resolveSeriesDeleteChoice("thisDate", bare) !== "nothing") fail("this-date-only falls through to " + sc.resolveSeriesDeleteChoice("thisDate", bare) + " when there is no day to skip: that is the incident with a dialog in front of it")
  const one = sc.planEntryDelete({ kind: "pencil", repeat: "", occurrenceDate: null })
  if (one.ask !== false || one.immediate !== "deleteRow") fail("a NON-repeating entry now asks before deleting, which is the noise that teaches people to click through the dialog that matters")
  if (sc.planEntrySave(rep).ask !== true) fail("saving a repeating entry no longer warns that it changes every date in the series")
  if (sc.planEntrySave({ kind: "pencil", repeat: "" }).ask !== false) fail("a non-repeating entry now asks before saving")
  if (sc.entryRepeats({ kind: "unavailable", repeat: "FREQ=WEEKLY" }) !== false) fail("a kind that cannot store a rule is treated as a series, so it would be asked about a series it does not have")
  if (!sc.SERIES_DELETE_COPY.seriesNote.includes("This cannot be undone.")) fail("the series delete no longer says it cannot be undone, and that missing sentence is what cost the owner their series")
  if (!/every date/.test(sc.SERIES_DELETE_COPY.seriesNote)) fail("the series delete no longer says it reaches every date")
  if (sc.SERIES_DELETE_COPY.thisDateLabel === sc.SERIES_DELETE_COPY.seriesLabel) fail("the two delete choices read the same, so the dialog does not offer a choice")
  const drawer = fs.readFileSync(DRAWER, "utf8")
  if (!/planEntryDelete\(/.test(drawer)) fail("the Details panel no longer routes Delete through planEntryDelete, so the decision above is not the one the button takes")
  if (!/if \(deletePlan\?\.ask\) setDeleting\(true\)/.test(drawer) || !/deleting && deletePlan\?\.ask \? \(\s*<SeriesDeleteDialog/.test(drawer)) fail("the Details panel no longer raises the series delete question from the plan")
  if (!/else if \(out\.kind === .ask.\) setSaveAsk\(out\)/.test(drawer) || !/<SeriesSaveDialog/.test(drawer)) fail("the Details panel no longer asks before saving a repeating date")
  if (!/remove\(choice === .thisDate. \? .day. : .row.\)/.test(drawer)) fail("the series choice no longer decides between skipping the day and deleting the row")
  const t = fs.readFileSync(TEST, "utf8")
  for (const pin of [
    "data-series-choice",
    "This cannot be undone.",
    "Delete the whole series",
    "This date only (Mon, Oct 19)",
    "Keep everything",
    "data-series-choice=\"save\"",
  ]) {
    if (!t.includes(pin)) fail("suite-details.render.test.tsx no longer pins the rendered dialog: " + pin + " is gone, so nothing measures what the operator actually sees")
  }
  if (!/skipDate\)\.toHaveBeenCalledTimes\(1\)/.test(t)) fail("the render test no longer proves that the one-date choice writes the exception date")
  if (!/deleteEntry\)\.not\.toHaveBeenCalled\(\)/.test(t)) fail("the render test no longer proves that the one-date choice leaves the row alone")
  if (!/toContain\([^)]*This cannot be undone/.test(t)) fail("the render test no longer asserts the irreversibility sentence is ON SCREEN, so the copy could be present in the module and absent from the dialog")
  if (!/deleteEntry\)\.toHaveBeenCalledTimes\(1\)/.test(t)) fail("the render test no longer proves the whole-series choice reaches the hard delete")
  if (!/skipDate\)\.mock\.calls\[0\]\)\.toEqual/.test(t)) fail("the render test no longer proves WHICH day the one-date choice skips")
  process.exit(0)
}).catch((e) => fail("lib/calendar/series-choice.ts could not be imported: " + String(e && e.message)))'
